# Helper for structured reading of values from a RustBuffer.
class RustBufferStream

  def initialize(rbuf)
    @rbuf = rbuf
    @offset = 0
  end

  def remaining
    @rbuf.len - @offset
  end

  def read(size)
    raise InternalError, 'read past end of rust buffer' if @offset + size > @rbuf.len

    data = @rbuf.data.get_bytes @offset, size

    @offset += size

    data
  end

  def readU64
    unpack_from 8, 'Q>'
  end

  def readI64
    unpack_from 8, 'q>'
  end

  def readF64
    unpack_from 8, 'G'
  end

  def readBool
    v = unpack_from 1, 'c'

    return false if v == 0
    return true if v == 1

    raise InternalError, 'Unexpected byte for Boolean type'
  end

  def readString
    size = unpack_from 4, 'l>'

    raise InternalError, 'Unexpected negative string length' if size.negative?

    read(size).force_encoding(Encoding::UTF_8)
  end

  def readBytes
    size = unpack_from 4, 'l>'

    raise InternalError, 'Unexpected negative byte string length' if size.negative?

    read(size).force_encoding(Encoding::BINARY)
  end

  # The Object type Browser.

  def readTypeBrowser
    handle = unpack_from 8, 'Q>'
    return Browser.uniffi_allocate(handle)
  end

  # The Object type Element.

  def readTypeElement
    handle = unpack_from 8, 'Q>'
    return Element.uniffi_allocate(handle)
  end

  # The Object type Page.

  def readTypePage
    handle = unpack_from 8, 'Q>'
    return Page.uniffi_allocate(handle)
  end

  # The Object type PluginHandle.

  def readTypePluginHandle
    handle = unpack_from 8, 'Q>'
    return PluginHandle.uniffi_allocate(handle)
  end

  # The Record type BrowserConfig.

  def readTypeBrowserConfig
    BrowserConfig.new(
      headless: readBool,
      detached: readBool,
      executable_path: readOptionalstring,
      plugins: readOptionalSequencestring
    )
  end

  

  

