  def readTypeXcelerateError
    variant = unpack_from 4, 'l>'
    
    if variant == 1
      return XcelerateError::WsError.new(
        readString()
      )
    end
    if variant == 2
      return XcelerateError::SerdeError.new(
        readString()
      )
    end
    if variant == 3
      return XcelerateError::CdpResponseError.new(
        readString()
      )
    end
    if variant == 4
      return XcelerateError::HttpError.new(
        readString()
      )
    end
    if variant == 5
      return XcelerateError::NotFound.new(
        readString()
      )
    end
    if variant == 6
      return XcelerateError::InternalError.new(
        readString()
      )
    end
    if variant == 7
      return XcelerateError::Unsupported.new(
        readString()
      )
    end

    raise InternalError, 'Unexpected variant tag for TypeXcelerateError'
  end
  

