# Helper for structured writing of values into a RustBuffer.
class RustBufferBuilder
  def initialize
    @rust_buf = RustBuffer.alloc 16
    @rust_buf.len = 0
  end

  def finalize
    rbuf = @rust_buf

    @rust_buf = nil

    rbuf
  end

  def discard
    return if @rust_buf.nil?

    rbuf = finalize
    rbuf.free
  end

  def write(value)
    reserve(value.bytes.size) do
      @rust_buf.data.put_array_of_char @rust_buf.len, value.bytes
    end
  end

  def write_U64(v)
    v = Xcelerate::uniffi_in_range(v, "u64", 0, 2**64)
    pack_into(8, 'Q>', v)
  end

  def write_I64(v)
    v = Xcelerate::uniffi_in_range(v, "i64", -2**63, 2**63)
    pack_into(8, 'q>', v)
  end

  def write_F64(v)
    pack_into(8, 'G', v)
  end

  def write_Bool(v)
    pack_into(1, 'c', v ? 1 : 0)
  end

  def write_String(v)
    v = Xcelerate::uniffi_utf8(v)
    pack_into 4, 'l>', v.bytes.size
    write v
  end

  def write_Bytes(v)
    v = Xcelerate::uniffi_bytes(v)
    pack_into 4, 'l>', v.bytes.size
    write v
  end

  # The Object type Browser.

  def write_TypeBrowser(obj)
    handle = Browser.uniffi_lower obj
    pack_into(8, 'Q>', handle)
  end

  # The Object type Element.

  def write_TypeElement(obj)
    handle = Element.uniffi_lower obj
    pack_into(8, 'Q>', handle)
  end

  # The Object type Page.

  def write_TypePage(obj)
    handle = Page.uniffi_lower obj
    pack_into(8, 'Q>', handle)
  end

  # The Object type PluginHandle.

  def write_TypePluginHandle(obj)
    handle = PluginHandle.uniffi_lower obj
    pack_into(8, 'Q>', handle)
  end

  # The Record type BrowserConfig.

  def write_TypeBrowserConfig(v)
    self.write_Bool(v.headless)
    self.write_Bool(v.detached)
    self.write_Optionalstring(v.executable_path)
    self.write_OptionalSequencestring(v.plugins)
  end

  

  # The Optional<T> type for string.

  def write_Optionalstring(v)
    if v.nil?
      pack_into(1, 'c', 0)
    else
      pack_into(1, 'c', 1)
      self.write_String(v)
    end
  end

  # The Optional<T> type for Sequencestring.

  def write_OptionalSequencestring(v)
    if v.nil?
      pack_into(1, 'c', 0)
    else
      pack_into(1, 'c', 1)
      self.write_Sequencestring(v)
    end
  end

  # The Sequence<T> type for string.

  def write_Sequencestring(items)
    pack_into(4, 'l>', items.size)

    items.each do |item|
      self.write_String(item)
    end
  end

  # The Sequence<T> type for TypeElement.

  def write_SequenceTypeElement(items)
    pack_into(4, 'l>', items.size)

    items.each do |item|
      self.write_TypeElement(item)
    end
  end

  

  private

  def reserve(num_bytes)
    if @rust_buf.len + num_bytes > @rust_buf.capacity
      @rust_buf = RustBuffer.reserve(@rust_buf, num_bytes)
    end

    yield

    @rust_buf.len += num_bytes
  end

  def pack_into(size, format, value)
    reserve(size) do
      @rust_buf.data.put_array_of_char @rust_buf.len, [value].pack(format).bytes
    end
  end
end

