  # Record type BrowserConfig
class BrowserConfig
  attr_reader :headless, :detached, :executable_path, :plugins

  def initialize(headless:, detached:, executable_path:, plugins:)
    @headless = headless
    @detached = detached
    @executable_path = executable_path
    @plugins = plugins
  end

  def ==(other)
    if @headless != other.headless
      return false
    end
    if @detached != other.detached
      return false
    end
    if @executable_path != other.executable_path
      return false
    end
    if @plugins != other.plugins
      return false
    end

    true
  end
end
  

  

  
